"""Generates taxonomy_data.rs (the inventory taxonomy v1's types and tables) from its contract.

The contract (ATLAS-api-harness crew/contracts/mk_taxonomy.md) holds the three tables as
markdown; this turns them into Rust static arrays, so 157 rows are never retyped by a model.
The Crew writes the lookups (taxonomy.rs) against this file.

    python tools/taxonomy_gen.py CONTRACT.md OUT.rs
"""
import re
import sys
from pathlib import Path

HEADER = '''//! The inventory taxonomy v1's types and tables: tool kinds, material kinds and the kits.
//!
//! Generated by tools/taxonomy_gen.py from the contract crew/contracts/mk_taxonomy.md
//! (ATLAS-api-harness), whose rows Claude chose and checked. Do not edit by hand: change the
//! contract and generate again. The lookups over these tables are in `taxonomy`.

/// How well a tool supplies a capability. Declared worst first, so Rough < Normal < Fine.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum Grade {
    Rough,
    Normal,
    Fine,
}

/// How loud a tool is, for the apartment-friendly checks.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Noise {
    Quiet,
    Moderate,
    Loud,
}

/// The forms of stock, in doc 04 section 4.3.2's order.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Form {
    Board,
    Sheet,
    Rod,
    Tube,
    Fabric,
    Roll,
    Block,
    SheetPaper,
    Filament,
    Liquid,
    Granular,
}

/// How the maker has a tool (doc 04 section 4.3.1's access field).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Access {
    Owned,
    Shared,
    Makerspace,
    Rentable,
    Wishlist,
}

/// A kind of tool.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ToolKind {
    pub id: &'static str,
    pub name: &'static str,
    /// Phrases a maker might write, already in `taxonomy::words_of` form.
    pub words: &'static [&'static str],
    /// As written in the table: "cut.straight", "cut.straight:rough", "drill.hole:fine".
    pub supplies: &'static [&'static str],
    pub noise: Noise,
}

/// A kind of material.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct MaterialKind {
    pub id: &'static str,
    pub name: &'static str,
    pub words: &'static [&'static str],
    /// The usual forms, the most usual first. Never empty.
    pub forms: &'static [Form],
    /// Must never be laser cut (doc 04: "laser-safe (PVC -> never)").
    pub laser_never: bool,
}

/// A fast-entry kit: pick it, then untick what you do not have.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Kit {
    pub id: &'static str,
    pub name: &'static str,
    pub access: Access,
    pub tools: &'static [&'static str],
}
'''


def section(text: str, heading: str) -> str:
    start = text.index(heading)
    end = text.find("\n## ", start + len(heading))
    return text[start: end if end != -1 else len(text)]


def rows(block: str) -> list[list[str]]:
    out = []
    for line in block.splitlines():
        if not line.startswith("| ") or line.startswith("| #") or line.startswith("|---"):
            continue
        cells = [c.strip() for c in line.strip().strip("|").split("|")]
        out.append(cells)
    return out


def strs(cell: str) -> str:
    if cell in ("", "-"):
        return "&[]"
    items = [p.strip() for p in cell.split(",")]
    for item in items:
        if not re.fullmatch(r"[A-Za-z0-9 ._:/()-]+", item) or '"' in item:
            sys.exit(f"odd item {item!r}")
    return "&[" + ", ".join(f'"{i}"' for i in items) + "]"


def name(cell: str) -> str:
    if '"' in cell or "\\" in cell:
        sys.exit(f"odd name {cell!r}")
    return f'"{cell}"'


def main() -> None:
    contract = Path(sys.argv[1]).read_text(encoding="utf-8")
    out = Path(sys.argv[2])

    caps_block = section(contract, "## Capabilities")
    caps_text = caps_block.split("exactly these 41 strings in this order:", 1)[1]
    caps = [c.strip() for c in caps_text.replace("\n", " ").split(",") if c.strip()]
    if len(caps) != 41:
        sys.exit(f"{len(caps)} capabilities")

    tools = rows(section(contract, "## Tool kinds"))
    materials = rows(section(contract, "## Material kinds"))
    kits = rows(section(contract, "## Kits"))
    if (len(tools), len(materials), len(kits)) != (67, 90, 8):
        sys.exit(f"counts {len(tools)} {len(materials)} {len(kits)}")

    lines = [HEADER]
    lines.append("/// The capability families: doc 04 section 4.3.1's v1 list in its order, then measure.photo.")
    lines.append(f"pub const CAPABILITIES: [&str; {len(caps)}] = [")
    lines += [f'    "{c}",' for c in caps]
    lines.append("];\n")

    lines.append("/// The tool kinds, in table order (the order breaks ties in word lookups).")
    lines.append(f"pub static TOOLS: [ToolKind; {len(tools)}] = [")
    for number, (num, tid, tname, words, supplies, noise) in enumerate(tools, 1):
        if int(num) != number:
            sys.exit(f"tool row {num} out of order")
        lines.append("    ToolKind {")
        lines.append(f'        id: "{tid}",')
        lines.append(f"        name: {name(tname)},")
        lines.append(f"        words: {strs(words)},")
        lines.append(f"        supplies: {strs(supplies)},")
        lines.append(f"        noise: Noise::{noise},")
        lines.append("    },")
    lines.append("];\n")

    lines.append("/// The material kinds, in table order.")
    lines.append(f"pub static MATERIALS: [MaterialKind; {len(materials)}] = [")
    for number, (num, mid, mname, words, forms, never) in enumerate(materials, 1):
        if int(num) != number:
            sys.exit(f"material row {num} out of order")
        form_list = ", ".join(f"Form::{f.strip()}" for f in forms.split(","))
        lines.append("    MaterialKind {")
        lines.append(f'        id: "{mid}",')
        lines.append(f"        name: {name(mname)},")
        lines.append(f"        words: {strs(words)},")
        lines.append(f"        forms: &[{form_list}],")
        lines.append(f"        laser_never: {'true' if never == 'yes' else 'false'},")
        lines.append("    },")
    lines.append("];\n")

    lines.append("/// The fast-entry kits (doc 04 section 4.3.1 names them and the first kit's contents).")
    lines.append(f"pub static KITS: [Kit; {len(kits)}] = [")
    for number, (num, kid, kname, access, ktools) in enumerate(kits, 1):
        if int(num) != number:
            sys.exit(f"kit row {num} out of order")
        lines.append("    Kit {")
        lines.append(f'        id: "{kid}",')
        lines.append(f"        name: {name(kname)},")
        lines.append(f"        access: Access::{access},")
        lines.append(f"        tools: {strs(ktools)},")
        lines.append("    },")
    lines.append("];")

    text = "\n".join(lines) + "\n"
    if any(ord(ch) > 127 for ch in text):
        sys.exit("non-ASCII in output")
    out.write_text(text, encoding="utf-8", newline="\n")
    print(f"{out}: {len(caps)} capabilities, {len(tools)} tools, {len(materials)} materials, {len(kits)} kits")


if __name__ == "__main__":
    main()
